<?php

declare(strict_types=1);

namespace Database\Seeders;

use App\Modules\Library\Infrastructure\Persistence\Models\LibraryArticle;
use App\Modules\Library\Infrastructure\Persistence\Models\LibraryCategory;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

final class LibraryMagicSkillsSeeder extends Seeder
{
    public function run(): void
    {
        DB::transaction(function (): void {
            $category = LibraryCategory::firstOrNew(['slug' => 'magicheskie-navyki']);
            if (! $category->exists) {
                $category->fill([
                    'name' => ['ru' => 'Магические навыки', 'uk' => 'Магічні навички'],
                    'description' => ['ru' => 'Заклинания, пассивные навыки, усиления и ослабления.', 'uk' => 'Закляття, пасивні навички, посилення та послаблення.'],
                    'is_active' => true,
                    'sort_order' => (int) LibraryCategory::max('sort_order') + 10,
                ]);
                $this->saveWithLegacy($category, ['name', 'description']);
            }

            foreach ([
                'combat' => ['boevye-magicheskie-navyki', 'Боевые заклинания', 'Бойові закляття'],
                'passive' => ['passivnye-magicheskie-navyki', 'Пассивные навыки', 'Пасивні навички'],
                'support' => ['baffy-debaffy-i-istselenie', 'Баффы, дебаффы и исцеление', 'Баффи, дебаффи та зцілення'],
            ] as $group => [$slug, $ruTitle, $ukTitle]) {
                if (LibraryArticle::withTrashed()->where('slug', $slug)->exists()) {
                    continue;
                }
                $article = new LibraryArticle([
                    'category_id' => $category->id,
                    'slug' => $slug,
                    'title' => ['ru' => $ruTitle, 'uk' => $ukTitle],
                    'excerpt' => [
                        'ru' => $ruTitle.': как работают навыки, их иконки и действующие эффекты.',
                        'uk' => $ukTitle.': як працюють навички, їхні іконки та чинні ефекти.',
                    ],
                    'content' => ['ru' => $this->content($group, false), 'uk' => $this->content($group, true)],
                    'status' => LibraryArticle::STATUS_PUBLISHED,
                    'published_at' => now(),
                    'sort_order' => (int) $category->articles()->max('sort_order') + 10,
                ]);
                $this->saveWithLegacy($article, ['title', 'excerpt', 'content']);
                $this->command?->info($ruTitle.': '.$article->id);
            }
        });
    }

    private function saveWithLegacy(LibraryCategory|LibraryArticle $model, array $fields): void
    {
        foreach ($fields as $field) {
            if (Schema::hasColumn($model->getTable(), $field.'_legacy')) {
                $model->setAttribute($field.'_legacy', $model->getTranslation($field, 'ru'));
            }
        }
        $model->save();
    }

    private function content(string $group, bool $uk): string
    {
        [$intro, $title, $guide] = match ($group) {
            'combat' => $uk ? [
                'Бойові закляття — активні прийоми, якими ви атакуєте супротивника. Одні завдають прямої шкоди, інші додатково залишають небезпечний ефект.',
                'Як користуватися бойовою магією',
                '<ol><li>Вивчіть закляття за відповідною книгою у наставника магії. Умови вивчення залежать від навички та характеристик персонажа.</li><li>Відкрийте <b>Персонаж → Магічні навички</b> та увімкніть потрібне закляття для показу в бою.</li><li>Для швидкого доступу додайте закляття до панелі через розділ слотів.</li><li>Стежте за маною та перезарядкою: повторний виклик під час відновлення не спрацює.</li></ol><p><b>Базова шкода в картці — лише частина розрахунку.</b> Підсумок також залежить від характеристик мага, сили закляття, захисту цілі та критичного удару.</p><p>Якщо закляття накладає ефект, у підказці вказані його шанс, тривалість і бонуси. Закляття, що спеціалізуються на послабленні цілі, описані в статті про баффи та дебаффи.</p>',
            ] : [
                'Боевые заклинания — активные приёмы, которыми вы атакуете противника. Одни наносят прямой урон, другие дополнительно оставляют опасный эффект.',
                'Как пользоваться боевой магией',
                '<ol><li>Изучите заклинание по соответствующей книге у наставника магии. Условия изучения зависят от навыка и характеристик персонажа.</li><li>Откройте <b>Персонаж → Магические навыки</b> и включите нужное заклинание для показа в бою.</li><li>Для быстрого доступа добавьте заклинание на панель через раздел слотов.</li><li>Следите за маной и перезарядкой: повторный вызов во время восстановления не сработает.</li></ol><p><b>Базовый урон в карточке — только часть расчёта.</b> Итог также зависит от характеристик мага, силы заклинания, защиты цели и критического удара.</p><p>Если заклинание накладывает эффект, в подсказке указаны его шанс, длительность и бонусы. Заклинания, специализирующиеся на ослаблении цели, описаны в статье о баффах и дебаффах.</p>',
            ],
            'passive' => $uk ? [
                'Пасивні навички посилюють персонажа без окремого застосування. Вони можуть збільшувати атаку чи захист, підсилювати магію або змінювати реакцію на небезпечні події в бою.',
                'Що дають пасивні навички',
                '<p><b>Сила удару</b> підсилює фізичну атаку, <b>Сила заклять</b> — магічну шкоду. <b>Загартована шкіра</b> та <b>Астральна шкіра</b> допомагають захищатися від фізичних і магічних атак.</p><p><b>Стійкість духу</b> скорочує дію ворожих дебаффів. <b>Інстинкт виживання</b> дає шанс пережити смертельний удар: це ймовірність, а не гарантований захист.</p><p>Вищі ранги мають власні вимоги та значення бонусів. Наведіть курсор на потрібний ранг, щоб порівняти його з іншими, а натискання відкриє повну інформацію.</p><p>Пасивні властивості вплавлених рун показані окремо в книзі заклять і залежать від спорядження, у яке вставлено руну. Кланові навички розглядаються в розділі бібліотеки <b>«Клан»</b>.</p>',
            ] : [
                'Пассивные навыки усиливают персонажа без отдельного применения. Они могут увеличивать атаку или защиту, усиливать магию либо менять реакцию на опасные события в бою.',
                'Что дают пассивные навыки',
                '<p><b>Сила удара</b> усиливает физическую атаку, <b>Сила заклинаний</b> — магический урон. <b>Закалённая кожа</b> и <b>Астральная кожа</b> помогают защищаться от физических и магических атак.</p><p><b>Стойкость духа</b> сокращает действие вражеских дебаффов. <b>Инстинкт выживания</b> даёт шанс пережить смертельный удар: это вероятность, а не гарантированная защита.</p><p>У высших рангов свои требования и значения бонусов. Наведите курсор на нужный ранг, чтобы сравнить его с другими, а нажатие откроет полную информацию.</p><p>Пассивные свойства вплавленных рун показаны отдельно в книге заклинаний и зависят от снаряжения, в которое вставлена руна. Клановые навыки рассматриваются в разделе библиотеки <b>«Клан»</b>.</p>',
            ],
            default => $uk ? [
                'Магія підтримки допомагає пережити складний бій: баффи посилюють ціль, лікування повертає здоров’я, а дебаффи послаблюють супротивника або заважають йому діяти.',
                'Посилення, лікування та послаблення',
                '<p><b>Баффи</b> тимчасово змінюють характеристики. Бойовий клич підсилює атаку, Кам’яна шкіра — броню, Благословення збільшує максимальні HP та MP. Точні бонуси залежать від рангу.</p><p><b>Миттєве лікування</b> одразу відновлює здоров’я, а <b>Регенерація</b> розподіляє його відновлення в часі. Вона працює в бою та поза боєм: часті удари не прискорюють лікування. Відсоток рахується від максимального HP на момент застосування.</p><p><b>Дебаффи</b> застосовуються до ворога. Вони можуть зменшувати характеристики, накладати періодичну шкоду чи контроль. Шанс і тривалість показані в підказці; окремі властивості цілі можуть скорочувати дію ефекту.</p><p>Для застосування потрібна мана та завершена перезарядка. Доступність союзної цілі визначається самим закляттям і присутністю гравця поруч. Тривалість ефекту та перезарядка — різні параметри: після завершення баффа закляття ще може відновлюватися.</p>',
            ] : [
                'Магия поддержки помогает пережить сложный бой: баффы усиливают цель, лечение возвращает здоровье, а дебаффы ослабляют противника или мешают ему действовать.',
                'Усиления, лечение и ослабления',
                '<p><b>Баффы</b> временно меняют характеристики. Боевой клич усиливает атаку, Каменная кожа — броню, Благословение увеличивает максимальные HP и MP. Точные бонусы зависят от ранга.</p><p><b>Мгновенное лечение</b> сразу восстанавливает здоровье, а <b>Регенерация</b> распределяет восстановление во времени. Она работает в бою и вне боя: частые удары не ускоряют лечение. Процент считается от максимального HP на момент применения.</p><p><b>Дебаффы</b> применяются к врагу. Они могут уменьшать характеристики, накладывать периодический урон или контроль. Шанс и длительность показаны в подсказке; отдельные свойства цели могут сокращать действие эффекта.</p><p>Для применения нужны мана и завершённая перезарядка. Доступность союзной цели определяется самим заклинанием и присутствием игрока рядом. Длительность эффекта и перезарядка — разные параметры: после завершения баффа заклинание ещё может восстанавливаться.</p>',
            ],
        };

        $catalog = '<p>'.($uk ? 'Наведіть курсор на іконку або картку, щоб побачити чинні параметри. Натисніть для докладної інформації.' : 'Наведите курсор на иконку или карточку, чтобы увидеть действующие параметры. Нажмите для подробной информации.').'</p>[[magic_skill_catalog:'.$group.']]';

        return '<p>'.$intro.'</p>'.$this->frame($title, $guide)
            .($group === 'combat' ? $this->frame($uk ? 'Каталог навичок' : 'Каталог навыков', $catalog) : $catalog);
    }

    private function frame(string $title, string $content): string
    {
        return '<table class="library-game-frame" border="0" cellspacing="0" cellpadding="0"><tbody><tr height="22"><td width="20" class="tbl-shp-sml lt"><b></b></td><td class="tbl-shp-sml tt" align="center"><table class="library-game-frame__title" border="0" cellspacing="0" cellpadding="0"><tbody><tr height="22"><td width="27"><img src="/img/bg/info/tbl-usi_label-left.gif" width="27" height="22" alt=""></td><td class="tbl-usi_label-center">'.e($title).'</td><td width="27"><img src="/img/bg/info/tbl-usi_label-right.gif" width="27" height="22" alt=""></td></tr></tbody></table></td><td width="20" class="tbl-shp-sml rt"><b></b></td></tr><tr><td class="tbl-shp-sides ls">&nbsp;</td><td class="tbl-usi_bg" valign="top" style="padding:8px 10px">'.$content.'</td><td class="tbl-shp-sides rs">&nbsp;</td></tr><tr height="18"><td width="20" class="tbl-shp-sml lb"><b></b></td><td class="tbl-shp-sml bb">&nbsp;</td><td width="20" class="tbl-shp-sml rb"><b></b></td></tr></tbody></table>';
    }
}
